INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(101537, 'ruRU', '', 'Ты не понимаешь, что блуждаешь в потёмках! Фело''мелорн был бы растрачен впустую в твоих руках!', 24330),
(101558, 'ruRU', '', 'Глупый смертный! Тебе стоило бежать, пока был шанс.', 24330),
(101590, 'ruRU', '', 'Счастливого пути, $n.', 24330),
(101591, 'ruRU', '', 'Используй мою дубильную стойку и верстак, чтобы изготовить всё необходимое. На моём верстаке ты также найдёшь дубильный раствор.', 24330),
(101592, 'ruRU', '', 'Надеюсь, ты сохранил свои материалы, они понадобятся тебе для финальной версии этих сапог.', 24330),
(101593, 'ruRU', '', 'Азоран должен умереть...', 24330),
(101595, 'ruRU', '', 'Мои глефы слишком долго не вкушали крови демонов...', 24330),
(101597, 'ruRU', '', 'Это заканчивается здесь и сейчас!', 24330),
(101603, 'ruRU', '', 'Майла, дитя, Подземный король уничтожил Речной Излом.', 24330),
(101604, 'ruRU', '', 'Спасибо, защитник. Теперь мы должны быть в безопасности. Идём, поговорим с Майлой.', 24330),
(101612, 'ruRU', '', 'Ты здесь, чтобы пополнить наши запасы? Если у тебя есть мясо, убедись, что оно не солёное. Транд говорит, солёное мясо портится быстрее.', 24330),
(101613, 'ruRU', '', 'Конечно, может, наши шляпы и кажутся тебе нелепыми, но они помогут нам быстро приспособиться к затоплению мира!', 24330),
(101616, 'ruRU', '', 'Они ведут себя как дети.$B$BИ всё же я знала, что это грядёт. Пожалуй, им стоит уладить свои разногласия прямо сейчас.', 24330),
(101619, 'ruRU', '', 'Пруд Правосудия может напомнить Кейну и Альтруису о нашем прошлом... общем прошлом, выкованном самим лордом Иллиданом.', 24330),
(101620, 'ruRU', '', 'Ох! Да, видишь ли, искатели приключений постоянно жалуются на то, что их скакуны время от времени сбрасывают их с сёдел, когда нападают враждебные существа.$b$bЯ говорила им перестать гонять через стаи диких зверей, но, очевидно, это "не самый быстрый способ передвижения".$b$bТак что я решила — раз уж не могу убедить их держаться дорог, возможно, проще будет смастерить для их скакунов доспехи, чтобы защитить их от всех этих нападений.$b$bГлавное, что нужно защитить — голова, шея и тело. Другими словами... практически всё.', 24330),
(101622, 'ruRU', '', 'Отличная работа, $n. Вот рецепты для каждой части конской брони, а также финальный рецепт сборки. Удачи!', 24330),
(101634, 'ruRU', '', 'Раны, нанесённые инцидентом с Божественным колоколом, глубоки, Этас. Остальные в совете не так снисходительны, как я.', 24330),
(101635, 'ruRU', '', 'Твой хозяин, демон. Где он прячется?', 24330),
(101637, 'ruRU', '', 'Ледяная Корона. Думаешь, найдёшь её там?', 24330),
(101643, 'ruRU', '', 'Пощады? Легион сжигает миры... а ты молишь о пощаде?', 24330),
(101644, 'ruRU', '', 'Быстрая смерть — больше милосердия, чем ты заслуживаешь.', 24330),
(101645, 'ruRU', '', 'Я представлю твоё дело перед остальными... но не могу обещать, что исход будет в твою пользу.', 24330),
(101671, 'ruRU', '', 'К оружию, $n. Сейчас не время бродить без дела. Если нужно, укройся внутри.', 24330),
(101672, 'ruRU', '', 'Прошу прощения, но сейчас не время, $c.', 24330),
(101691, 'ruRU', '', 'Продолжим охоту!', 24330),
(101711, 'ruRU', '', 'Тебе не избежать правосудия!', 24330),
(101717, 'ruRU', '', 'Брандольф! Живучий щенок! Я уж думал, что сгнию в той клетке. А это кто, $r?', 24330),
(101726, 'ruRU', '', 'Кожаные игрушки для питомцев? Так, посмотрим... новый поводок был бы неплох. И я знаю, питомцы оценили бы мягкую уютную лежанку для отдыха.$b$bЯ всегда мечтал смастерить для них обруч, через который можно прыгать. Желательно такой, который можно поджечь. Вот это был бы настоящий трюк!', 24330),
(101727, 'ruRU', '', 'Кожаные игрушки для питомцев? Так, посмотрим... новый поводок был бы неплох. И я знаю, питомцы оценили бы мягкую уютную лежанку для отдыха.$b$bЯ всегда мечтал смастерить для них обруч, через который можно прыгать. Желательно такой, который можно поджечь. Вот эт'' был бы настоящий трюк!', 24330),
(101739, 'ruRU', '', 'Ты умрёшь во имя Сашь''тар!', 24330),
(101740, 'ruRU', '', 'Яндвик падёт!', 24330),
(101741, 'ruRU', '', 'Как видишь, наш бывший коллега выполнил своё обещание о помощи. Надеюсь, ты учтёшь это, рассматривая его просьбу о возвращении в город.', 24330),
(101745, 'ruRU', '', 'Ты пришёл, как и говорила Эммарел.', 24330),
(101748, 'ruRU', '', 'Рад тебя видеть. Нам нужно заглянуть в Высокогорье, прежде чем достигнуть конечной цели — Штормхейма.', 24330),
(101774, 'ruRU', '', 'Это было проще, чем ожидалось. Должно быть, большинство квалдиров сейчас в набеге.', 24330),
(101776, 'ruRU', '', 'Вухо! Ты нашёл чудовище?', 24330),
(101778, 'ruRU', '', 'Нужно найти путь! Вухо, нам с тобой стоит осмотреть обереги, пока $n обыскивает гавань.', 24330),
(101781, 'ruRU', '', 'Ты что, слепой? Убейте их!', 24330),
(101783, 'ruRU', '', 'Следующему падающему инферналу лучше не задеть ещё одного страйдера. У нас заканчиваются припасы!', 24330),
(101784, 'ruRU', '', 'Если я сегодня увижу ещё одного уничтоженного страйдера, я... я... Поверь мне — случится что-то плохое!', 24330);
